#!/usr/bin/env bash
# Build Spek.app on this Mac using Homebrew (Intel /usr/local or Apple Silicon /opt/homebrew).
# Usage:
#   ./dist/osx/build-local-app.sh           # build Spek.app
#   ./dist/osx/build-local-app.sh --dmg     # also create Spek.dmg
#   ./dist/osx/build-local-app.sh --clean   # clean before build
#   JOBS=8 ./dist/osx/build-local-app.sh

set -euo pipefail

ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
OSXdir="$ROOT/dist/osx"
APP="$OSXdir/Spek.app"
MAKE_DMG=0
DO_CLEAN=0
JOBS="${JOBS:-$(sysctl -n hw.ncpu 2>/dev/null || echo 4)}"

for arg in "$@"; do
  case "$arg" in
    --dmg) MAKE_DMG=1 ;;
    --clean) DO_CLEAN=1 ;;
    -h|--help)
      sed -n '2,8p' "$0"
      exit 0
      ;;
    *)
      echo "Unknown option: $arg" >&2
      exit 1
      ;;
  esac
done

die() { echo "error: $*" >&2; exit 1; }
info() { echo "==> $*"; }

# --- Homebrew ---
if command -v brew >/dev/null 2>&1; then
  BREW_PREFIX="$(brew --prefix)"
else
  die "Homebrew not found. Install from https://brew.sh"
fi

export PATH="$BREW_PREFIX/bin:$BREW_PREFIX/sbin:$BREW_PREFIX/opt/gettext/bin:${PATH:-}"
export PKG_CONFIG_PATH="$BREW_PREFIX/lib/pkgconfig:${PKG_CONFIG_PATH:-}"
export ACLOCAL_PATH="$BREW_PREFIX/share/aclocal:${ACLOCAL_PATH:-}"
export LDFLAGS="-L$BREW_PREFIX/lib ${LDFLAGS:-}"
export CPPFLAGS="-I$BREW_PREFIX/include ${CPPFLAGS:-}"

# Prefer native arch (arm64 on Apple Silicon, x86_64 on Intel)
HOST_ARCH="$(uname -m)"
export CFLAGS="-arch $HOST_ARCH ${CFLAGS:-}"
export CXXFLAGS="-arch $HOST_ARCH -std=gnu++11 ${CXXFLAGS:-}"
export LDFLAGS="-arch $HOST_ARCH $LDFLAGS"

need_pkgs=()
for pkg in automake autoconf libtool pkg-config gettext ffmpeg wxwidgets; do
  if ! brew list --formula "$pkg" >/dev/null 2>&1; then
    # pkg-config may be pkgconf on newer Homebrew
    if [[ "$pkg" == "pkg-config" ]] && brew list --formula pkgconf >/dev/null 2>&1; then
      continue
    fi
    need_pkgs+=("$pkg")
  fi
done
if ((${#need_pkgs[@]})); then
  info "Installing missing Homebrew packages: ${need_pkgs[*]}"
  brew install "${need_pkgs[@]}"
fi

command -v wx-config >/dev/null || die "wx-config not in PATH (wxwidgets)"
command -v pkg-config >/dev/null || die "pkg-config not in PATH"
command -v autoreconf >/dev/null || die "autoreconf not in PATH"

# wxwin.m4 defines AM_OPTIONS_WXCONFIG / AM_PATH_WXCONFIG used by configure.ac.
# Needed only for autoreconf (generating configure), not for compiling or bundling.
# Official dist/osx/README.md does this as a manual step before bundle.sh.
WX_PREFIX="$(brew --prefix wxwidgets 2>/dev/null || true)"
WX_M4=""
# Homebrew layout: share/wx/<ver>/aclocal/wxwin.m4
for candidate in "$WX_PREFIX"/share/wx/*/aclocal/wxwin.m4; do
  if [[ -f "$candidate" ]]; then
    WX_M4="$candidate"
    break
  fi
done
if [[ -z "$WX_M4" || ! -f "$WX_M4" ]]; then
  WX_M4="$(find -L "${WX_PREFIX:-/nonexistent}" -name wxwin.m4 2>/dev/null | head -n1 || true)"
fi
[[ -n "$WX_M4" && -f "$WX_M4" ]] || die "wxwin.m4 not found (wxwidgets prefix=${WX_PREFIX:-none}). Expected under share/wx/*/aclocal/"
mkdir -p "$BREW_PREFIX/share/aclocal"
if [[ ! -e "$BREW_PREFIX/share/aclocal/wxwin.m4" ]]; then
  info "Linking wxwin.m4 -> $WX_M4"
  ln -sf "$WX_M4" "$BREW_PREFIX/share/aclocal/wxwin.m4"
fi
# Ensure aclocal/autoreconf can see it even if brew share/aclocal is not default
export ACLOCAL_PATH="$BREW_PREFIX/share/aclocal:${ACLOCAL_PATH:-}"

# wxstd catalog version (3.2 / 3.3 / ...)
WX_LOCALE_ROOT="$(brew --prefix wxwidgets)/share/locale"
WXSTD_MO_NAME=""
if [[ -d "$WX_LOCALE_ROOT" ]]; then
  WXSTD_MO_NAME="$(find "$WX_LOCALE_ROOT" -name 'wxstd-*.mo' 2>/dev/null | head -1 | xargs -I{} basename {} || true)"
fi

LANGUAGES="bs ca cs da de el eo es fi fr gl he hr hu id it ja ko lv nb nl nn pl pt_BR ru sk sr@latin sv th tr uk vi zh_CN zh_TW"

cd "$ROOT"

if [[ "$DO_CLEAN" -eq 1 ]]; then
  info "Cleaning"
  if [[ -f Makefile ]]; then
    make distclean || true
  fi
  rm -rf "$APP" "$OSXdir/Spek.dmg" "$OSXdir/Spek.dmg.master" "$OSXdir/Spek.mounted"
fi

info "Configuring (arch=$HOST_ARCH, prefix=$BREW_PREFIX)"
chmod +x "$ROOT/autogen.sh" 2>/dev/null || true
# NOCONFIGURE then configure explicitly so env flags apply cleanly
NOCONFIGURE=1 ./autogen.sh
./configure \
  --prefix="$BREW_PREFIX" \
  --disable-dependency-tracking

info "Building (jobs=$JOBS)"
make -j"$JOBS"

[[ -x "$ROOT/src/spek" ]] || die "src/spek was not built"
file "$ROOT/src/spek" | grep -q "$HOST_ARCH" || \
  echo "warning: binary arch may not match host ($HOST_ARCH): $(file "$ROOT/src/spek")"

# --- Assemble .app ---
info "Assembling Spek.app"
rm -rf "$APP"
mkdir -p \
  "$APP/Contents/MacOS" \
  "$APP/Contents/Frameworks" \
  "$APP/Contents/Resources"

# Info.plist is generated by configure from Info.plist.in
if [[ -f "$OSXdir/Info.plist" ]]; then
  cp "$OSXdir/Info.plist" "$APP/Contents/"
else
  die "dist/osx/Info.plist missing (configure should generate it from Info.plist.in)"
fi

cp "$ROOT/src/spek" "$APP/Contents/MacOS/Spek"
chmod +x "$APP/Contents/MacOS/Spek"
cp "$OSXdir/Spek.icns" "$APP/Contents/Resources/"
cp "$OSXdir"/*.png "$APP/Contents/Resources/" 2>/dev/null || true
cp "$ROOT/CREDITS.md" "$ROOT/LICENSE" "$ROOT/README.md" "$APP/Contents/Resources/"
mkdir -p "$APP/Contents/Resources/lic"
cp "$ROOT/lic/"* "$APP/Contents/Resources/lic/" 2>/dev/null || true

for lang in $LANGUAGES; do
  mkdir -p "$APP/Contents/Resources/${lang}.lproj"
  if [[ -f "$ROOT/po/${lang}.gmo" ]]; then
    cp "$ROOT/po/${lang}.gmo" "$APP/Contents/Resources/${lang}.lproj/spek.mo"
  fi
  if [[ -n "$WXSTD_MO_NAME" && -f "$WX_LOCALE_ROOT/$lang/LC_MESSAGES/$WXSTD_MO_NAME" ]]; then
    cp "$WX_LOCALE_ROOT/$lang/LC_MESSAGES/$WXSTD_MO_NAME" \
      "$APP/Contents/Resources/${lang}.lproj/" || true
  fi
done
mkdir -p "$APP/Contents/Resources/en.lproj"

# Bundle Homebrew dylibs (absolute paths + @rpath/@loader_path) and rewrite load commands.
# Crash root-cause example: libwebpdemux kept @rpath/libwebp.7.dylib which resolves to
# Frameworks/../lib (missing). Must rewrite to @executable_path/../Frameworks/...
info "Bundling shared libraries from $BREW_PREFIX"
FW="$APP/Contents/Frameworks"
EXE="$APP/Contents/MacOS/Spek"

is_system_dep() {
  case "$1" in
    /usr/lib/*|/System/*|/usr/lib/system/*) return 0 ;;
    *) return 1 ;;
  esac
}

# Locate a dylib on the build machine by soname (e.g. libwebp.7.dylib).
find_host_lib() {
  local name="$1"
  local p
  for p in \
    "$BREW_PREFIX/lib/$name" \
    "$BREW_PREFIX/opt/webp/lib/$name" \
    "$BREW_PREFIX/opt"/*/lib/"$name"
  do
    if [[ -e "$p" ]]; then
      realpath "$p"
      return 0
    fi
  done
  # Last resort: search Cellar (follows symlinks with -L)
  p="$(find -L "$BREW_PREFIX/Cellar" "$BREW_PREFIX/lib" -name "$name" 2>/dev/null | head -n1 || true)"
  if [[ -n "$p" && -e "$p" ]]; then
    realpath "$p"
    return 0
  fi
  return 1
}

# Copy lib into Frameworks; keep soname symlink when realpath basename differs.
# Prints the Frameworks file basename to use in @executable_path references.
stage_lib() {
  local src="$1"
  local reallib libname soname
  reallib="$(realpath "$src")"
  libname="$(basename "$reallib")"
  soname="$(basename "$src")"

  if [[ ! -f "$FW/$libname" ]]; then
    # Log to stderr so command substitutions only capture the basename
    echo "  + $reallib" >&2
    cp "$reallib" "$FW/$libname"
    chmod u+w "$FW/$libname"
    install_name_tool -id "@executable_path/../Frameworks/$libname" "$FW/$libname"
  fi
  # e.g. libwebp.7.dylib -> libwebp.7.2.0.dylib so @rpath sonames still resolve if needed
  if [[ "$soname" != "$libname" ]]; then
    ln -sfn "$libname" "$FW/$soname"
  fi
  # ONLY basename on stdout (used by libname="$(stage_lib ...)")
  printf '%s' "$libname"
}

# Resolve one otool dependency string to a host filesystem path, if possible.
resolve_dep_on_host() {
  local dep="$1"
  local loader="$2"
  local name base dir candidate rpath

  if is_system_dep "$dep"; then
    return 1
  fi
  if [[ "$dep" == @executable_path/../Frameworks/* ]]; then
    return 1
  fi
  if [[ -e "$dep" ]]; then
    realpath "$dep"
    return 0
  fi

  name="${dep##*/}"

  if [[ "$dep" == @loader_path/* ]]; then
    dir="$(dirname "$loader")"
    candidate="$dir/${dep#@loader_path/}"
    if [[ -e "$candidate" ]]; then
      realpath "$candidate"
      return 0
    fi
  fi

  if [[ "$dep" == @rpath/* ]]; then
    # Search LC_RPATH of the loader, then Homebrew lib dirs
    while IFS= read -r rpath; do
      [[ -z "$rpath" ]] && continue
      rpath="${rpath//@loader_path/$(dirname "$loader")}"
      rpath="${rpath//@executable_path/$(dirname "$EXE")}"
      candidate="$rpath/${dep#@rpath/}"
      if [[ -e "$candidate" ]]; then
        realpath "$candidate"
        return 0
      fi
    done < <(otool -l "$loader" 2>/dev/null | awk '/LC_RPATH/{getline; getline; if ($1=="path") print $2}' || true)
  fi

  find_host_lib "$name"
}

bundle_one() {
  local bin="$1"
  local dep hostlib libname
  local deps

  deps="$(otool -L "$bin" 2>/dev/null | awk 'NR>1 {print $1}' || true)"
  for dep in $deps; do
    is_system_dep "$dep" && continue
    [[ "$dep" == @executable_path/../Frameworks/* ]] && continue

    hostlib="$(resolve_dep_on_host "$dep" "$bin" || true)"
    if [[ -z "$hostlib" || ! -e "$hostlib" ]]; then
      # Already only a Frameworks-relative name we don't recognize — skip
      continue
    fi

    libname="$(stage_lib "$hostlib")"
    install_name_tool -change "$dep" "@executable_path/../Frameworks/$libname" "$bin" 2>/dev/null || true
  done
}

# BFS over executable + staged dylibs until no new libs appear
chmod u+w "$EXE"
bundle_one "$EXE"
changed=1
while [[ "$changed" -eq 1 ]]; do
  changed=0
  for f in "$FW"/*.dylib; do
    [[ -f "$f" && ! -L "$f" ]] || continue
    chmod u+w "$f" 2>/dev/null || true
    before="$(ls -1 "$FW" 2>/dev/null | wc -l | tr -d ' ')"
    bundle_one "$f"
    after="$(ls -1 "$FW" 2>/dev/null | wc -l | tr -d ' ')"
    if [[ "$after" -gt "$before" ]]; then
      changed=1
    fi
  done
done

# Final pass: rewrite any remaining @rpath/@loader_path/absolute brew paths
info "Fixing remaining install names"
fix_targets=("$EXE")
for f in "$FW"/*.dylib; do
  [[ -f "$f" && ! -L "$f" ]] && fix_targets+=("$f")
done
for bin in "${fix_targets[@]}"; do
  chmod u+w "$bin" 2>/dev/null || true
  while IFS= read -r dep; do
    [[ -z "$dep" ]] && continue
    is_system_dep "$dep" && continue
    [[ "$dep" == @executable_path/../Frameworks/* ]] && continue
    name="${dep##*/}"
    if [[ -e "$FW/$name" ]]; then
      # Prefer real file if symlink
      if [[ -L "$FW/$name" ]]; then
        target="$(readlink "$FW/$name")"
        install_name_tool -change "$dep" "@executable_path/../Frameworks/$target" "$bin" 2>/dev/null || true
      else
        install_name_tool -change "$dep" "@executable_path/../Frameworks/$name" "$bin" 2>/dev/null || true
      fi
      continue
    fi
    hostlib="$(resolve_dep_on_host "$dep" "$bin" || true)"
    if [[ -n "$hostlib" && -e "$hostlib" ]]; then
      libname="$(stage_lib "$hostlib")"
      install_name_tool -change "$dep" "@executable_path/../Frameworks/$libname" "$bin" 2>/dev/null || true
    else
      echo "warning: unresolved dependency $dep (from $(basename "$bin"))" >&2
    fi
  done < <(otool -L "$bin" 2>/dev/null | awk 'NR>1 {print $1}' || true)
done

# Verify no @rpath left
if otool -L "$EXE" "$FW"/*.dylib 2>/dev/null | grep -E '@rpath/|@loader_path/' >/dev/null; then
  echo "warning: some @rpath/@loader_path entries remain:" >&2
  otool -L "$EXE" "$FW"/*.dylib 2>/dev/null | grep -E '@rpath/|@loader_path/|:' | grep -B1 -E '@rpath/|@loader_path/' || true
fi

# Ad-hoc sign so Gatekeeper is less noisy on local runs (must be after install_name_tool)
if command -v codesign >/dev/null 2>&1; then
  info "Ad-hoc codesign"
  codesign --force --deep -s - "$APP" 2>/dev/null || \
    echo "warning: codesign failed (app may still run locally)"
fi

info "Built: $APP"
file "$APP/Contents/MacOS/Spek"
echo "Run: open \"$APP\""

if [[ "$MAKE_DMG" -eq 1 ]]; then
  info "Creating DMG"
  VOLUME_NAME=Spek
  DMG_FILE="$OSXdir/$VOLUME_NAME.dmg"
  MOUNT_POINT="$OSXdir/$VOLUME_NAME.mounted"
  rm -f "$DMG_FILE" "$DMG_FILE.master"
  rm -rf "$MOUNT_POINT"

  image_size="$(du -ck "$APP" | tail -n1 | cut -f1)"
  image_size="$(( (image_size + 5000) / 1000 ))"

  hdiutil create "$DMG_FILE" -megabytes "$image_size" -volname "$VOLUME_NAME" -fs HFS+ -quiet
  hdiutil attach "$DMG_FILE" -readwrite -noautoopen -mountpoint "$MOUNT_POINT" -quiet
  cp -Rp "$APP" "$MOUNT_POINT/"
  ln -s /Applications "$MOUNT_POINT/ "
  [[ -f "$OSXdir/DS_Store" ]] && cp "$OSXdir/DS_Store" "$MOUNT_POINT/.DS_Store"
  hdiutil detach "$MOUNT_POINT" -quiet
  mv "$DMG_FILE" "$DMG_FILE.master"
  hdiutil convert -quiet -format UDBZ -o "$DMG_FILE" "$DMG_FILE.master"
  rm -f "$DMG_FILE.master"
  info "DMG: $DMG_FILE"
fi

info "Done."
